'use strict';

class Counter {
  #hits;

  constructor() {
    this.#hits = [];
  }

  record() {
    this.#hits.push(Date.now());
  }

  count(windowMs) {
    const now = Date.now();
    const lowerBoundary = now - windowMs;
    const retained = [];
    let count = 0;

    for (const timestamp of this.#hits) {
      if (timestamp < lowerBoundary) {
        continue;
      }

      retained.push(timestamp);
      if (timestamp <= now) {
        count += 1;
      }
    }

    this.#hits = retained;
    return count;
  }
}

module.exports = Counter;

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const projectRoot = path.resolve(__dirname, '..');

function loadCounter() {
  return require(projectRoot);
}

function mockNow(t, values) {
  const originalNow = Date.now;
  let calls = 0;

  Date.now = () => {
    if (calls >= values.length) {
      throw new Error(`Date.now called more than the expected ${values.length} time(s)`);
    }
    return values[calls++];
  };

  t.after(() => {
    Date.now = originalNow;
  });

  return {
    calls() {
      return calls;
    }
  };
}

test('package root directly exports the Counter class with exact public arities', () => {
  const Counter = loadCounter();

  assert.equal(typeof Counter, 'function');
  assert.equal(Counter.name, 'Counter');
  assert.match(Function.prototype.toString.call(Counter), /^class\s+Counter\b/);
  assert.equal(Counter.length, 0);
  assert.equal(Counter.prototype.record.length, 0);
  assert.equal(Counter.prototype.count.length, 1);

  const counter = new Counter();
  assert.ok(counter instanceof Counter);
  assert.throws(() => Counter(), TypeError, 'Counter must be a class requiring new');
});

test('a new counter returns integer zero and count captures time once', (t) => {
  const Counter = loadCounter();
  const clock = mockNow(t, [1234]);
  const counter = new Counter();

  const result = counter.count(500);
  assert.strictEqual(result, 0);
  assert.equal(typeof result, 'number');
  assert.equal(Number.isInteger(result), true);
  assert.equal(clock.calls(), 1);
});

test('record returns undefined, captures one timestamp, and preserves duplicate hits', (t) => {
  const Counter = loadCounter();
  const clock = mockNow(t, [100, 100, 100]);
  const counter = new Counter();

  assert.strictEqual(counter.record(), undefined);
  assert.equal(clock.calls(), 1);
  assert.strictEqual(counter.record(), undefined);
  assert.equal(clock.calls(), 2);

  assert.strictEqual(counter.count(0), 2);
  assert.equal(clock.calls(), 3, 'count must capture the current time exactly once');
});

test('the inclusive lower boundary is counted while a hit one millisecond older is pruned', (t) => {
  const Counter = loadCounter();
  mockNow(t, [99, 100, 110, 99]);
  const counter = new Counter();

  counter.record(); // Older than the eventual lower boundary by 1ms.
  counter.record(); // Exactly on the eventual lower boundary.

  assert.strictEqual(counter.count(10), 1);

  // At this earlier time, the 99ms hit would be in range if it had not been
  // irreversibly pruned. The retained 100ms hit is future-dated and excluded.
  assert.strictEqual(counter.count(100), 0);
});

test('a zero-duration window counts only current hits, prunes older hits, and retains future hits', (t) => {
  const Counter = loadCounter();
  mockNow(t, [49, 50, 51, 50, 51, 49]);
  const counter = new Counter();

  counter.record();
  counter.record();
  counter.record();

  assert.strictEqual(counter.count(0), 1, 'only the hit at time 50 is current');
  assert.strictEqual(counter.count(0), 1, 'the future hit at 51 must have remained retained');
  assert.strictEqual(
    counter.count(100),
    0,
    'the hit at 49 was pruned and the retained 50/51 hits are future-dated'
  );
});

test('pruning by a short window is irreversible when a later window is larger', (t) => {
  const Counter = loadCounter();
  mockNow(t, [0, 95, 100, 100]);
  const counter = new Counter();

  counter.record();
  counter.record();

  assert.strictEqual(counter.count(10), 1);
  assert.strictEqual(counter.count(1000), 1, 'the pruned hit must not reappear');
});

test('nonchronological timestamps are evaluated individually regardless of storage position', (t) => {
  const Counter = loadCounter();
  mockNow(t, [100, 10, 80, 70, 20, 100]);
  const counter = new Counter();

  // Deliberately store an old timestamp between two future timestamps.
  counter.record(); // 100
  counter.record(); // 10
  counter.record(); // 80

  assert.strictEqual(
    counter.count(20),
    0,
    'at time 70, timestamps 80 and 100 are future-dated and 10 must be pruned'
  );
  assert.strictEqual(
    counter.count(20),
    0,
    'moving back to time 20 must not recover the previously pruned timestamp 10'
  );
  assert.strictEqual(
    counter.count(30),
    2,
    'future-dated retained hits must become countable when time reaches them'
  );
});

test('package declares no external dependencies and retains the node test script', () => {
  const packagePath = path.join(projectRoot, 'package.json');
  const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));

  for (const field of [
    'dependencies',
    'devDependencies',
    'optionalDependencies',
    'peerDependencies'
  ]) {
    assert.deepStrictEqual(pkg[field] || {}, {}, `${field} must contain no declarations`);
  }

  assert.equal(pkg.scripts && pkg.scripts.test, 'node --test');
});
